#!/usr/bin/env python3
import os
import sys


def extract_license(split_license):
    assert split_license != None

    license = ""

    for line in split_license:
        license += line

    return license


def get_license():
    f = open("src/catch2/catch_all.hpp", "r")
    license = extract_license(f.readlines()[0:7])
    f.close()
    return license


def check_license(license):
    failed = 0
    base_dir = "src/catch2/"

    # The _ represents the list of directories in base_dir
    for root, _, files in os.walk(base_dir):
        for file in files:
            f = open(root + "/" + file, "r")
            file_license = ""
            split_license = extract_license(f.readlines()[0:7])

            for line in split_license:
                file_license += line

            if file_license != license:
                print("File %s does not have license" % file)

    copy(self, "src/*", src=self.recipe_folder, dst=self.export_sources_folder)
    copy(self, "extras/*", src=self.recipe_folder, dst=self.export_sources_folder)
    copy(self, "CMake/*", src=self.recipe_folder, dst=self.export_sources_folder)

def config_options(self):
    if self.settings.os == "Windows":
        del self.options.fPIC

def configure(self):
    if self.options.shared:
        self.options.rm_safe("fPIC")

def layout(self):
    cmake_layout(self)

def validate(self):
    if self.settings.compiler.get_safe("cppstd"):
        check_min_cppstd(self, self._min_cppstd)
    # INFO: Conan 1.x does not specify cppstd by default, so we need to check the compiler version instead.
    minimum_version = self._compilers_minimum_version.get(str(self.settings.compiler), False)
    if minimum_version and Version(self.settings.compiler.version) < minimum_version:
        raise ConanInvalidConfiguration(f"{self.ref} requires C++{self._min_cppstd}, which your compiler doesn't support")

def generate(self):
    tc = CMakeToolchain(self)
    tc.cache_variables["BUILD_TESTING"] = False
    tc.cache_variables["CATCH_INSTALL_DOCS"] = False
    tc.cache_variables["CATCH_INSTALL_EXTRAS"] = True
    tc.generate()

    deps = CMakeDeps(self)
    deps.generate()

def build(self):
    cmake = CMake(self)
    cmake.configure()
    cmake.build()

def package(self):
    copy(self, "LICENSE.txt", src=str(self.recipe_folder), dst=os.path.join(self.package_folder, "licenses"))
    cmake = CMake(self)
    cmake.install()
    rmdir(self, os.path.join(self.package_folder, "share"))
    rmdir(self, os.path.join(self.package_folder, "lib", "cmake"))
    for cmake_file in ["ParseAndAddCatchTests.cmake", "Catch.cmake", "CatchAddTests.cmake"]:
        copy(
            self,
            cmake_file,
            src=os.path.join(self.export_sources_folder, "extras"),
            dst=os.path.join(self.package_folder, "lib", "cmake", "Catch2"),
        )

