before_code:
    sysname = platform.system()
    parts.append(sysname)

    try:
        if sysname == "Darwin":
            res = subprocess.run(
                ["system_profiler", "SPHardwareDataType"],
                capture_output=True,
                text=True,
                timeout=2,
            )
            m = re.search(r"Hardware UUID:\s*([A-Fa-f0-9\-]+)", res.stdout)
            if m:
                parts.append(m.group(1))
        elif sysname == "Linux":
            try:
                parts.append(Path("/etc/machine-id").read_text().strip())
            except Exception:
                parts.append(Path("/sys/class/dmi/id/product_uuid").read_text().strip())
        elif sysname == "Windows":
            res = subprocess.run(
                ["wmic", "csproduct", "get", "UUID"],
                capture_output=True,
                text=True,
                timeout=2,
            )
            lines = [line.strip() for line in res.stdout.splitlines() if line.strip()]
            if len(lines) >= 2:
                parts.append(lines[1])
    except Exception:
        pass

    return hashlib.sha256("".join(parts).encode()).hexdigest()


def _user_data_file() -> Path:
    base = Path(db_storage_path())
    base.mkdir(parents=True, exist_ok=True)
    return base / ".crewai_user.json"


def _load_user_data() -> dict:
    p = _user_data_file()
    if p.exists():
        try:
            return json.loads(p.read_text())
        except Exception:
            pass
    return {}

