def stream_chat(
    self, messages: Sequence[ChatMessage], **kwargs: Any
) -> ChatResponseGen:
    content = self._content_from_content_blocks(messages[-1].blocks)
    if not content:
        content = "<empty>"
    response_msg = ChatMessage(role="assistant", content=content)

    def _gen():
        yield ChatResponse(
            message=response_msg,
            delta=content,
            raw={"content": content},
        )

    return _gen()

