def register_context(name: str, tenant_id: str, provider: Callable[[], BaseModel]) -> None:
    """Register a tenant-specific provider for a named context."""
    _tenant_context_providers.setdefault(name, {})[tenant_id] = provider


def read_context(name: str, *, tenant_id: str) -> T:
    """
    Read a context value for a specific tenant.

    Raises KeyError if the provider for (name, tenant_id) is not registered.
    """
    providers = _tenant_context_providers.get(name, {})
    prov = providers.get(tenant_id)
    if prov is None:
        raise KeyError(f"Context provider '{name}' not registered for tenant '{tenant_id}'")
    return prov()


