            inputs[k] = v.model_dump()
        elif isinstance(v, list):
            v_list = cast(list[Any], v)
            if all(isinstance(item, File) for item in v_list):
                inputs[k] = [item.model_dump() for item in v_list if isinstance(item, File)]
    self._inputs = inputs

