    self,
    repro: models.Repro,
    debug_command: Optional[str],
) -> Optional[str]:
    """Setup an SSH tunnel, then connect via CDB over SSH tunnel"""

    if (
        repro.auth is None
        or repro.ip is None
        or repro.state != enums.VmState.running
    ):
