def extract_and_convert_fraction(text):
    pattern = r"^\\frac\{(\d+)\}\{(\d+)\}$"
    match = re.match(pattern, text)
    if match:
        numerator, denominator = match.groups()
        return float(numerator) / float(denominator)

    pattern = r"^\\frac(\d)(\d)$"
    match = re.match(pattern, text)
    if match:
        numerator, denominator = match.groups()
        return float(numerator) / float(denominator)

    pattern = r"^-\\frac\{(\d+)\}\{(\d+)\}$"
    match = re.match(pattern, text)
    if match:
        numerator, denominator = match.groups()
        return -float(numerator) / float(denominator)

