    Returns:
        Set of selector names.
    """
    selectors: set[str] = {
        "*",
        *(f".{class_name}" for class_name in self._classes),
        *self._css_types,
    }
    if self._id is not None:
        selectors.add(f"#{self._id}")
    return selectors

