            identifier, version = Checkpoint.parse_uri(self.adapter_id)
            version = int(version)
            checkpoint = db.load("checkpoint", identifier, version=version)
            assert checkpoint, f"Checkpoint {self.adapter_id} not found"
            self.adapter_id = checkpoint

