from textual.layouts.grid import GridLayout


async def test_grid_size():
    """Test the `grid_size` property on GridLayout."""

    class GridApp(App):
        CSS = """
        Grid {
            grid-size: 3;
            grid-columns: auto;
            height: auto;
            Label {
                padding: 2 4;
                border: blue;
            }
        }
        """

