def _add_section_name(query):
    # temporary solution before we don't find a fixed one
    if ' ' not in query and '+' not in query:
        return query
    if '/' in query:
        return query

    delim = None
    if ' ' in query:
        delim = " "
    elif '+' in query:
        delim = "+"


    if delim:
        index = 0
        length = len(query)
        while index != length:

            index = query.index(delim, index) + 1

            try:
                comparison = query.index(delim, index)
            except ValueError:
                comparison = -1

            if (index != comparison and index != length):
                return "%s/%s" % (query[:index-1], query[index:])

    return query

