    type=str,
    help="Comma-separated list of synonyms",
    required=False,
)
@click.pass_context
def glossary_add(
    ctx: click.Context,
    agent_id: str,
    name: str,
    description: str,
    synonyms: Optional[str],
) -> None:
    agent_id = agent_id if agent_id else Interface.get_default_agent(ctx)
    assert agent_id

    Interface.create_term(ctx, agent_id, name, description, synonyms)

