        self.assertFalse(is_valid_email('john.doe@gmail'))

    def test_is_valid_phone_number(self):
        self.assertTrue(is_valid_phone_number('+1 (123) 456-7890'))
        self.assertFalse(is_valid_phone_number('123-456-789'))

