                name, value = cookie.split("=")
                self['cookies'][name.strip()] = {'value': value.strip()}
            del request_headers['Cookie']
            continue

        for prefix in SESSION_IGNORED_HEADER_PREFIXES:
            if name.lower().startswith(prefix.lower()):
                break
        else:
            headers[name] = value

    self['headers'] = dict(headers)

