def get_tokens_unprocessed(self, text):
    """Parse JSON data."""

    in_body_prefix = False

    for index, token, value in super().get_tokens_unprocessed(text):
        if token is Token.Punctuation and self.body_prefix_sep in value:
            # `value` can be a single character or a sequence of punctuation characters.
            # We need to iterate over the whole `value` to properly handle the body prefix
            # separator from actual JSON punctuation characters.
            for char in value:
                if char == self.body_prefix_sep:
                    # Body prefix.
                    in_body_prefix = not in_body_prefix
                elif in_body_prefix:
                    # Punctuation character part of the body prefix.
                    yield index, self.body_prefix_token, char
                else:
                    # Punctuation character outside the body prefix.
                    yield index, token, char
        elif in_body_prefix:
            # `value` is part of the body prefix.
            yield index, self.body_prefix_token, value
        else:
            # Outside the body prefix.
