def format_headers(self, headers: str) -> str:
    for p in self.enabled_plugins:
        headers = p.format_headers(headers)
    return headers

def format_body(self, content: str, mime: str) -> str:
    if is_valid_mime(mime):
        for p in self.enabled_plugins:
            content = p.format_body(content, mime)
    return content

def option(self, *names: List[str], default: Any = None) -> Any:
    """Get the value of a format option referenced by `*names`.
    Return `default` when the option does not exist.

        >>> cls = Formatting('', format_options={'json': {'format': True}})
        >>> cls.option()
        >>> cls.option(default=42)
        42
        >>> cls.option('json')
        {'format': True}
        >>> cls.option('json', 'format')
        True
        >>> cls.option('unknown', 'sub', 'key')
        >>> cls.option('unknown', 'key', default=42)
        42
    """
    if not names:
        return default

    lookup = self.format_options
    for name in names:
        try:
            lookup = lookup[name]
        except KeyError:
            return default
    return lookup

