    try:
        socket.inet_aton(string_ip)
    except BaseException:
        return False
    return True


def is_ipv4_network(string_network):
    if '/' in string_network:
        try:
            socket.inet_aton(string_network.split('/')[0])
        except OSError:
            return False
    else:
        return False
    return True


