    if res['code'] == '422':
        self.sf.error("Usage quota reached. Insufficient API Credit")
        self.errorState = True
        return None

    if res['code'] == '429':
        self.sf.error("Too many requests")
        self.errorState = True
        return None

    if res['code'] == '500' or res['code'] == '503':
